fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    // If the coefficient grid is exactly 1×1, return that single coefficient.
    // Otherwise, the default is 0.0.
    if c.len() == 1 && c[0].len() == 1 {
        c[0][0]
    } else {
        0.0
    }
}

fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Preconditions
    assert_eq!(
        x.len(),
        y.len(),
        "Input arrays `x` and `y` must have the same length"
    );
    assert!(
        !x.is_empty(),
        "Input arrays must have positive length"
    );
    assert!(
        !c.is_empty(),
        "Coefficient grid must be non-empty"
    );
    for row in &c {
        assert!(
            !row.is_empty(),
            "Each row in the coefficient grid must be non-empty"
        );
    }

    let n = x.len();
    let dv = default_value(&c);

    // If the grid is 1×1, fill the output with that single coefficient;
    // otherwise fill with zeros.
    if c.len() == 1 && c[0].len() == 1 {
        vec![dv; n]
    } else {
        vec![0.0; n]
    }
}

